-- Full exercise library and pre-made plans, exported from the original database.
-- Twelve exercises were added outside migrations there, so a fresh database needs
-- this to match. Safe to re-run: rows are upserted.

ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name,
  movement_type = EXCLUDED.movement_type,
  equipment_type = EXCLUDED.equipment_type,
  target = EXCLUDED.target,
  instructions = EXCLUDED.instructions,
  setup_cue = EXCLUDED.setup_cue,
  position_cue = EXCLUDED.position_cue,
  movement_cue = EXCLUDED.movement_cue,
  video_url = EXCLUDED.video_url,
  alternative_exercise_id = EXCLUDED.alternative_exercise_id;

ON CONFLICT (equipment_type, day_number) DO UPDATE SET
  exercise_ids_list = EXCLUDED.exercise_ids_list,
  target_sets = EXCLUDED.target_sets,
  target_reps = EXCLUDED.target_reps;
